73	QThreadStorageData::~QThreadStorageData()
74	{
75	    DEBUG_MSG("QThreadStorageData: Released id %d", id);
76	    QMutexLocker locker(&destructorsMutex);
77	    if (destructors())
78	        (*destructors())[id] = nullptr;
79	}
